def comps_of(g):
    fill=Counter(x for r in g for x in r).most_common(1)[0][0]
    hrows=[i for i,r in enumerate(g) if fill not in r]
    vcols=[j for j in range(len(g[0])) if all(g[i][j]!=fill for i in range(len(g)))]
    mk={}
    for i in hrows:
        for j in vcols:
            c=g[i][j]
            if c!=fill: mk[(i,j)]=c
    # group into comps by color
    bycol={}
    for (i,j),c in mk.items(): bycol.setdefault(c,[]).append((i,j))
    res={}
    for c,pts in bycol.items():
        rs=sorted({p[0] for p in pts}); cs=sorted({p[1] for p in pts})
        # room indices within marked lattice
        ri=[hrows.index(r) for r in rs]; ci=[vcols.index(x) for x in cs]
        res[c]=(ri,ci)
    return hrows,vcols,res
